#include <stdio.h>
typedef struct T { int v; struct T *l, *r; } T;
T d = {4, 0, 0}, e = {5, 0, 0};
T b = {2, 0, 0}, c = {3, &d, &e};
T a = {1, &b, &c};
int leaves(T *n) {
    if (!n) return 0;
    if (!n->l && !n->r) return 1;
    return leaves(n->l) + leaves(n->r);
}
int main(void) { printf("%d\n", leaves(&a)); return 0; }

