#include <stdio.h>
typedef struct T { int v; struct T *l, *r; } T;
T e = {5, 0, 0};
T d = {4, 0, 0};
T b = {2, &d, 0}, c = {3, 0, &e};
T a = {1, &b, &c};
int h(T *n) {
    if (!n) return -1;
    int x = h(n->l), y = h(n->r);
    return 1 + (x > y ? x : y);
}
int main(void) { printf("%d\n", h(&a)); return 0; }

#include <stdio.h>
typedef struct T { int v; struct T *l, *r; } T;
